#import "TFAIConversationTimeline.h"
#import "TFAIActivity.h"
static NSString *S(id value){return [value isKindOfClass:NSString.class]?value:@"";}
static NSString *JSON(id value){if([value isKindOfClass:NSString.class])return value;if(!value)return @"{}";if(![NSJSONSerialization isValidJSONObject:value])return [value description];return [[NSString alloc]initWithData:[NSJSONSerialization dataWithJSONObject:value options:NSJSONWritingPrettyPrinted error:nil] encoding:NSUTF8StringEncoding]?:@"{}";}
NSArray *TFAIConversationTimeline(NSArray *messages,NSArray *records,NSDictionary *summaries,NSString *legacySummary,NSDictionary *folds){
 NSMutableDictionary *messageSlots=[NSMutableDictionary new],*callSlots=[NSMutableDictionary new],*resultSlots=[NSMutableDictionary new],*buckets=[NSMutableDictionary new];NSMutableSet *used=[NSMutableSet new],*toolOwners=[NSMutableSet new];
 for(NSUInteger i=0;i<messages.count;i++){NSDictionary *m=messages[i];if(S(m[@"messageID"]).length)messageSlots[m[@"messageID"]]=@(i*3);for(NSDictionary *call in m[@"tool_calls"])if(S(call[@"id"]).length){callSlots[call[@"id"]]=@(i*3+2);[toolOwners addObject:@(i)];}if([m[@"role"] isEqual:@"tool"]&&S(m[@"tool_call_id"]).length)resultSlots[m[@"tool_call_id"]]=@(i*3);}
 void(^add)(NSUInteger,NSDictionary *)=^(NSUInteger slot,NSDictionary *row){NSNumber *key=@(slot);if(!buckets[key])buckets[key]=[NSMutableArray new];[buckets[key] addObject:row];};
 for(NSDictionary *r in records){NSString *identifier=S(r[@"id"]);if(!identifier.length||[used containsObject:identifier])continue;[used addObject:identifier];NSNumber *slot=callSlots[identifier]?:resultSlots[identifier];NSNumber *anchor=messageSlots[r[@"assistantMessageID"]?:@""];if(anchor)[toolOwners addObject:@(anchor.unsignedIntegerValue/3)];if(!slot&&anchor){slot=@(anchor.unsignedIntegerValue+2);[toolOwners addObject:@(anchor.unsignedIntegerValue/3)];}
 // Old sessions retain tool_call_id linkage. Timestamp is only a fallback for interrupted/orphan records.
 if(!slot&&[r[@"time"] isKindOfClass:NSNumber.class]){double time=[r[@"time"] doubleValue];for(NSUInteger i=0;i<messages.count;i++){id stamp=messages[i][@"timestamp"];if([stamp isKindOfClass:NSNumber.class]&&[stamp doubleValue]<=time)slot=@(i*3+2);}}
 if(!slot)slot=@(messages.count*3+2);NSString *state=S(r[@"status"]);BOOL open=folds[identifier]?[folds[identifier] boolValue]:[@[@"failed",@"waitingApproval",@"interrupted"] containsObject:state];if([state isEqual:@"waitingApproval"])open=YES;NSString *title=TFAIActivityTitle(r),*detail=TFAIActivityDetail(r);add(slot.unsignedIntegerValue,@{@"role":[state isEqual:@"failed"]?@"error":@"process",@"rowID":[@"process-" stringByAppendingString:identifier],@"foldID":identifier,@"content":[title stringByAppendingFormat:@"\n%@\n%@",JSON(r[@"arguments"]),JSON(r[@"result"])],@"display":open?detail:[title stringByAppendingString:@"  ⌄"],@"processRecord":[r copy],@"foldTitle":title,@"expanded":@(open)});}
 for(NSUInteger i=0;i<messages.count;i++){NSDictionary *m=messages[i];NSString *role=m[@"role"];if([@[@"system",@"tool"] containsObject:role])continue;NSString *mid=S(m[@"messageID"]),*summary=S(summaries[mid]);if(summary.length){NSString *fold=[@"summary-" stringByAppendingString:mid];BOOL open=[folds[fold] boolValue];add(i*3,@{@"role":@"process",@"rowID":fold,@"foldID":fold,@"content":summary,@"foldTitle":@"分析摘要",@"expanded":@(open),@"display":open?summary:@"分析摘要 · 点击展开"});}if([role isEqual:@"assistant"]&&!S(m[@"content"]).length&&([m[@"tool_calls"] count]||[toolOwners containsObject:@(i)]))continue;NSMutableDictionary *row=[m mutableCopy];if([toolOwners containsObject:@(i)])row[@"intermediate"]=@YES;row[@"rowID"]=mid.length?[@"message-" stringByAppendingString:mid]:[NSString stringWithFormat:@"message-%lu",(unsigned long)i];add(i*3+1,row);}
 if(!summaries.count&&legacySummary.length){BOOL open=[folds[@"summary"] boolValue];add(messages.count*3+1,@{@"role":@"process",@"rowID":@"summary",@"foldID":@"summary",@"content":legacySummary,@"foldTitle":@"分析摘要",@"expanded":@(open),@"display":open?legacySummary:@"分析摘要 · 点击展开"});}
 NSMutableArray *out=[NSMutableArray new];for(NSNumber *key in [[buckets allKeys] sortedArrayUsingSelector:@selector(compare:)])[out addObjectsFromArray:buckets[key]];return out;
}
NSArray<NSDictionary *> *TFAIConversationWithStatus(NSArray *timeline,BOOL active,NSString *status,NSString *activeMessageID){
 if(!active)return timeline?:@[];NSMutableArray *out=[NSMutableArray new];
 for(NSDictionary *row in timeline){if([row[@"role"] isEqual:@"assistant"]&&[row[@"messageID"] isEqual:activeMessageID]&&!S(row[@"content"]).length&&![row[@"attachments"] count]&&![row[@"images"] count])continue;[out addObject:row];}
 NSString *text=[S(status) stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceAndNewlineCharacterSet];if(!text.length)text=@"正在响应";
 [out addObject:@{@"role":@"process",@"rowID":@"live-status",@"content":text,@"processing":@YES}];return out;
}

NSArray<NSDictionary *> *TFAIConversationGrouped(NSArray *timeline,NSDictionary *folds){
 NSMutableArray *out=[NSMutableArray new],*turn=[NSMutableArray new];__block NSString *turnID=@"legacy";
 void (^flush)(void)=^{
  if(!turn.count)return;NSInteger final=-1;for(NSUInteger i=0;i<turn.count;i++){NSDictionary *r=turn[i];if([r[@"role"] isEqual:@"assistant"]&&![r[@"tool_calls"] count]&&![r[@"intermediate"] boolValue]&&S(r[@"content"]).length)final=i;}
  NSMutableArray *details=[NSMutableArray new],*answers=[NSMutableArray new];for(NSUInteger i=0;i<turn.count;i++){NSDictionary *r=turn[i];if((NSInteger)i==final||([r[@"role"] isEqual:@"error"]&&!r[@"foldID"]))[answers addObject:r];else if(S(r[@"content"]).length||r[@"foldID"])[details addObject:r];}
  if(details.count){NSString *key=[@"turn-" stringByAppendingString:turnID];BOOL open=[folds[key] boolValue];NSString *title=[NSString stringWithFormat:@"处理过程 · %lu 项",(unsigned long)details.count];[out addObject:@{@"role":@"process",@"rowID":key,@"foldID":key,@"foldTitle":title,@"content":@"",@"display":@"",@"expanded":@(open),@"groupHeader":@YES}];if(open)for(NSDictionary *r in details){NSMutableDictionary *child=[r mutableCopy];child[@"nested"]=@YES;[out addObject:child];}}
  [out addObjectsFromArray:answers];[turn removeAllObjects];
 };
 for(NSDictionary *r in timeline){if([r[@"role"] isEqual:@"user"]){flush();turnID=S(r[@"messageID"]).length?r[@"messageID"]:r[@"rowID"]?:@"legacy";[out addObject:r];}else[turn addObject:r];}flush();return out;
}

NSArray<NSDictionary *> *TFAIConversationTimed(NSArray *timeline,NSDictionary *timings,NSTimeInterval now){
 NSMutableArray *out=[NSMutableArray new];for(NSDictionary *row in timeline){if(![row[@"groupHeader"] boolValue]){NSDictionary *record=row[@"processRecord"];if([record[@"status"] isEqual:@"running"]&&[record[@"startedAt"] isKindOfClass:NSNumber.class]&&!record[@"duration"]){NSMutableDictionary *live=[record mutableCopy];live[@"duration"]=@(MAX(0,now-[record[@"startedAt"] doubleValue]));NSMutableDictionary *copy=[row mutableCopy];copy[@"foldTitle"]=TFAIActivityTitle(live);[out addObject:copy];}else[out addObject:row];continue;}NSString *key=S(row[@"foldID"]);NSDictionary *time=[key hasPrefix:@"turn-"]?timings[[key substringFromIndex:5]]:nil;if(![time isKindOfClass:NSDictionary.class]||![time[@"start"] isKindOfClass:NSNumber.class]){[out addObject:row];continue;}NSTimeInterval elapsed=time[@"duration"]?[time[@"duration"] doubleValue]:MAX(0,now-[time[@"start"] doubleValue]);if(!isfinite(elapsed)||elapsed<0){[out addObject:row];continue;}NSString *duration=elapsed<60?[NSString stringWithFormat:@"%.1f 秒",elapsed]:[NSString stringWithFormat:@"%lu 分 %02lu 秒",(unsigned long)elapsed/60,(unsigned long)elapsed%60];NSMutableDictionary *copy=[row mutableCopy];copy[@"baseFoldTitle"]=row[@"baseFoldTitle"]?:row[@"foldTitle"];copy[@"foldTitle"]=[NSString stringWithFormat:@"%@ · %@%@",row[@"baseFoldTitle"]?:row[@"foldTitle"],time[@"end"]?@"用时 ":@"已处理 ",duration];[out addObject:copy];}return out;
}
